T1="P1-M4-7.1"; T2="P1-M4-7.2"
Q=[
(T1,"RICD",[21],"E","A Procuradoria Parlamentar é constituída por sete membros designados pelo Presidente da Câmara a cada quatro anos.","Art. 21, § 1º: onze membros, designados a cada dois anos, no início da sessão legislativa.","quorum"),
(T1,"RICD",["21B"],"C","A Ouvidoria Parlamentar é composta de um Ouvidor-Geral e dois Ouvidores Substitutos, designados pelo Presidente da Câmara dentre os membros da Casa, vedada a recondução no período subsequente.","Art. 21-B.","quorum"),
(T1,"RICD",["21E"],"C","O Conselho de Ética e Decoro Parlamentar é composto de 21 membros titulares e igual número de suplentes, com mandato de 2 anos.","Art. 21-E, caput e § 1º.","quorum"),
(T1,"RICD",["21F"],"E","Nas hipóteses de perda de mandato dos incisos IV e V do art. 55 da CF, a Câmara reexamina o mérito da decisão judicial.","Art. 21-F, p.ú.: análise restrita aos aspectos formais da decisão judicial.","competencia"),
(T1,"RICD",["21G"],"C","A Corregedoria Parlamentar é composta por 1 Corregedor e 3 Corregedores Substitutos.","Art. 21-G.","quorum"),
(T2,"RICD",[65],"C","As sessões ordinárias deliberativas realizam-se apenas uma vez por dia, de terça a quinta-feira, com início às quatorze horas.","Art. 65, II, a.","prazo"),
(T2,"RICD",[65],"E","As sessões solenes têm duração máxima de seis horas.","Art. 65, III, b: prazo não excedente a quatro horas.","prazo"),
(T2,"RICD",[65],"C","As sessões preparatórias são as que precedem a inauguração dos trabalhos do Congresso Nacional na primeira e na terceira sessões legislativas de cada legislatura.","Art. 65, I.","tipo"),
(T2,"RICD",[65],"E","As sessões de debates ocorrem às segundas e sextas-feiras, têm duração de três horas e contam com Ordem do Dia.","Art. 65, III, a: cinco horas e sem Ordem do Dia.","tipo"),
(T2,"RICD",[66],"E","Nas sessões ordinárias, a Ordem do Dia inicia-se às dezoito horas.","Art. 66, III: às dezesseis horas.","prazo"),
(T2,"RICD",[66],"C","Nas sessões ordinárias, o Grande Expediente tem duração improrrogável de cinquenta minutos, distribuída entre os oradores inscritos.","Art. 66, II.","prazo"),
(T2,"RICD",[66],"C","O Presidente da Câmara poderá não designar Ordem do Dia para sessões ordinárias, que se converterão em sessões de debates.","Art. 66, § 3º.","podedeve"),
(T2,"RICD",[66],"E","Durante os períodos de sessões extraordinárias exclusivas de discussão e votação, as sessões ordinárias continuam a ser realizadas e as Comissões Permanentes seguem funcionando.","Art. 66, § 5º: não serão realizadas sessões ordinárias nem funcionarão as Comissões Permanentes.","podedeve"),
(T2,"RICD",[67],"C","A sessão extraordinária destina-se exclusivamente à discussão e votação das matérias constantes da Ordem do Dia.","Art. 67, caput.","leitura"),
(T2,"RICD",[68],"E","A Câmara pode realizar até cinco sessões solenes por mês, por deliberação do Plenário.","Art. 68, III: até duas sessões solenes a cada mês.","quorum"),
(T2,"RICD",[68],"C","A sessão solene independe de número e nela só usarão da palavra os oradores previamente designados pelo Presidente.","Art. 68, II.","podedeve"),
(T2,"RICD",[69],"C","As sessões da Câmara são públicas, mas excepcionalmente poderão ser secretas, quando assim deliberado pelo Plenário.","Art. 69.","leitura"),
(T2,"RICD",[70],"E","O Presidente pode suspender a sessão quantas vezes julgar necessário, por até duas horas cada vez.","Art. 70: uma única vez, pelo prazo máximo de uma hora, findo o qual considera-se encerrada.","prazo"),
(T2,"RICD",[71],"C","A sessão pode ser levantada antes do prazo previsto, entre outras hipóteses, em caso de tumulto grave ou falecimento de Chefe de um dos Poderes da República.","Art. 71, I e II.","leitura"),
(T2,"RICD",[71],"E","A sessão pode ser levantada antes do término se a presença nos debates for inferior a um terço do total de Deputados.","Art. 71, III: menos de um décimo.","quorum"),
(T2,"RICD",[73],"C","Só Deputados e Senadores podem ter assento no Plenário, ressalvado o disposto no art. 77, §§ 2º e 3º.","Art. 73, I.","leitura"),
(T2,"RICD",[73],"E","Durante a sessão, o Presidente falará de pé e os demais Deputados, sentados.","Art. 73, III: o Presidente falará sentado e os demais Deputados, de pé, salvo impossibilidade física.","leitura"),
(T2,"RICD",[73],"C","Ao falar da bancada, o orador em nenhuma hipótese poderá fazê-lo de costas para a Mesa.","Art. 73, V.","podedeve"),
(T2,"RICD",[73],"E","O Deputado que insistir em falar antirregimentalmente, após advertência, será suspenso da sessão pelo Presidente.","Art. 73, VII: o Presidente dará o seu discurso por terminado.","competencia"),
(T2,"RICD",[74],"E","O Deputado pode falar a qualquer momento, desde que peça a palavra ao Presidente.","Art. 74: só pode falar nas hipóteses expressas do Regimento (proposição, comunicação, questão de ordem, reclamação, encaminhamento etc.).","podedeve"),
(T2,"RICD",[75],"C","O Deputado inscrito que não puder falar entregará à Mesa discurso escrito para publicação, dispensando-se a leitura.","Art. 75, caput.","leitura"),
(T2,"RICD",[75],"E","Para o Pequeno Expediente, os discursos entregues por escrito não podem ultrapassar dez laudas.","Art. 75, I: três laudas datilografadas em espaço dois.","quorum"),
(T2,"RICD",[77],"C","No recinto do Plenário, durante as sessões, só serão admitidos Deputados e Senadores, ex-parlamentares, funcionários da Câmara em serviço local e jornalistas credenciados.","Art. 77, caput.","leitura"),
(T2,"RICD",[77],"E","Ao público é franqueado o acesso ao recinto do Plenário para assistir às sessões.","Art. 77, § 4º: acesso às galerias circundantes, mantida a incomunicabilidade com o recinto.","podedeve"),
(T2,"RICD",[78],"C","A transmissão por rádio ou televisão e a gravação das sessões da Câmara dependem de prévia autorização do Presidente.","Art. 78.","competencia"),
(T2,"RICD",[79],"C","Presente pelo menos a décima parte do número total de Deputados, desprezada a fração, o Presidente declarará aberta a sessão.","Art. 79, § 2º.","quorum"),
(T2,"RICD",[79],"E","Não havendo quórum de presença para abrir a sessão, o Presidente aguardará durante uma hora que ele se complete.","Art. 79, § 3º: meia hora.","prazo"),
(T2,"RICD",[80],"C","A ata da sessão anterior é lida pelo Segundo-Secretário e considerada aprovada pelo Presidente, independentemente de votação.","Art. 80, caput.","competencia"),
]
